package com.wingedsheep.engine.scenarios

import com.wingedsheep.engine.support.GameTestDriver
import com.wingedsheep.engine.support.TestCards
import com.wingedsheep.sdk.core.Color
import com.wingedsheep.sdk.core.Step
import com.wingedsheep.sdk.model.Deck
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe

/**
 * Bite Down (DMU #155) — {1}{G} Instant.
 *
 * "Target creature you control deals damage equal to its power to target creature or planeswalker
 *  you don't control."
 *
 * Generated by mtgish-tooling, whose target recovery read the IR's `ControlledByAPlayer(Other(You))`
 * as a bare `You` and rendered `.youControl()` on the SECOND target — so both halves pointed at the
 * caster's own board and the spell could only ever shoot the caster's own creatures.
 */
class BiteDownScenarioTest : FunSpec({

    fun newDriver(): GameTestDriver {
        val driver = GameTestDriver()
        driver.registerCards(TestCards.all)
        driver.initMirrorMatch(Deck.of("Forest" to 40), skipMulligans = true, startingPlayer = 0)
        driver.passPriorityUntil(Step.PRECOMBAT_MAIN)
        return driver
    }

    test("the damaged creature must be one you don't control") {
        val driver = newDriver()
        val yours = driver.putCreatureOnBattlefield(driver.player1, "Grizzly Bears") // 2/2
        val alsoYours = driver.putCreatureOnBattlefield(driver.player1, "Minotaur Warrior") // 2/3

        val bite = driver.putCardInHand(driver.player1, "Bite Down")
        driver.giveMana(driver.player1, Color.GREEN, 2)
        // Both targets on your own side is an illegal targeting — the second requirement is
        // "creature or planeswalker you don't control".
        driver.castSpell(driver.player1, bite, listOf(yours, alsoYours)).isSuccess shouldBe false
    }

    test("your creature deals damage equal to its power to the opponent's creature") {
        val driver = newDriver()
        val yours = driver.putCreatureOnBattlefield(driver.player1, "Grizzly Bears") // 2/2
        val theirs = driver.putCreatureOnBattlefield(driver.player2, "Minotaur Warrior") // 2/3

        val bite = driver.putCardInHand(driver.player1, "Bite Down")
        driver.giveMana(driver.player1, Color.GREEN, 2)
        driver.castSpell(driver.player1, bite, listOf(yours, theirs)).isSuccess shouldBe true
        driver.bothPass()

        // 2 damage is non-lethal to a 2/3, and it's one-sided — your Bears takes nothing back.
        driver.findPermanent(driver.player2, "Minotaur Warrior") shouldBe theirs
        driver.findPermanent(driver.player1, "Grizzly Bears") shouldBe yours
    }
})
